import React from 'react';
import { FormLabel, Heading, HStack, Input, Stack } from '@chakra-ui/react';

import { detailModalSettingInputs, toolbarButtonSettingInputs } from '../../lib';

import type { ICalendarPlusSettings } from '../../lib';

interface IFormattingSettingsProps {
	settings: ICalendarPlusSettings;
	handleInputChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
}

export const FormattingSettings: React.FunctionComponent<IFormattingSettingsProps> = ({
	settings,
	handleInputChange,
}) => {
	if (!settings) {
		return <></>;
	}

	return (
		<>
			<Heading mb={4}>Text Labels</Heading>
			<FormLabel fontWeight={700}>Toolbar button labels</FormLabel>
			<Stack spacing={4}>
				{toolbarButtonSettingInputs.map(({ id, label }) => (
					<HStack spacing={4} align='center' key={id}>
						<FormLabel htmlFor={id} mb={0} ml={6} minW='300px' fontWeight={400}>
							{label}
						</FormLabel>
						<Input id={id} value={settings[id] ?? ''} onChange={handleInputChange} flex='1' />
					</HStack>
				))}
			</Stack>

			<FormLabel mt={6} fontWeight={700}>
				Event detail modal labels
			</FormLabel>
			<Stack spacing={4}>
				{detailModalSettingInputs.map(({ id, label }) => (
					<HStack spacing={4} align='center' key={id}>
						<FormLabel htmlFor={id} mb={0} ml={6} minW='300px' fontWeight={400}>
							{label}
						</FormLabel>
						<Input id={id} value={settings[id] ?? ''} onChange={handleInputChange} flex='1' />
					</HStack>
				))}
			</Stack>
		</>
	);
};
