import React, { useCallback, useState } from 'react';
import { Slider, SliderTrack, SliderFilledTrack, SliderThumb, Text, Box, HStack, Divider } from '@chakra-ui/react';
import type { ICalendarPlusSettings } from '../../../../lib';

const radiusOptions = ['none', 'sm', 'md', 'lg', 'xl', '2xl'];

interface IRadiusSettingsProps {
	settings: ICalendarPlusSettings;
	updateSettings: (updates: Partial<ICalendarPlusSettings>) => void;
}
export const RadiusSettings = ({ settings, updateSettings }: IRadiusSettingsProps) => {
	const [selectedView, setSelectedView] = useState('toolbar');

	const handleSelectView = useCallback((element) => {
		const { id } = element.target;
		setSelectedView(id);
	}, []);

	const handleSliderChange = useCallback(
		(value) => {
			const radiusValue = radiusOptions[value];

			if (selectedView === 'toolbar') {
				updateSettings({ radius: { ...settings.radius, toolbar: radiusValue } });
			} else {
				updateSettings({ radius: { ...settings.radius, calendarView: radiusValue } });
			}
		},
		[settings, selectedView, updateSettings]
	);

	const currentToolbarRadiusIndex = radiusOptions.indexOf(settings.radius.toolbar);
	const currentCalendarRadiusIndex = radiusOptions.indexOf(settings.radius.calendarView);

	return (
		<Box>
			<Box mx={6}>
				<Text mb={4}>Select the radius:</Text>
				<Slider
					step={1}
					value={selectedView === 'toolbar' ? currentToolbarRadiusIndex : currentCalendarRadiusIndex}
					min={0}
					max={5}
					onChange={handleSliderChange}
				>
					<SliderTrack>
						<SliderFilledTrack />
					</SliderTrack>
					<SliderThumb />
				</Slider>
				<HStack justify='space-between' mt={2}>
					{radiusOptions.map((option, index) => (
						<Text
							key={option}
							fontSize='sm'
							margin='0px !important'
							ml={index === 1 ? '-23px !important' : 0}
						>
							{option}
						</Text>
					))}
				</HStack>
			</Box>

			<Divider my={4} />
			{/* Calendar Preview */}
			<Text mb={4}>Choose the section to change its radius:</Text>
			<Box>
				<Box
					onClick={handleSelectView}
					id='toolbar'
					borderRadius={settings.radius.toolbar}
					border={selectedView === 'toolbar' ? '2px solid' : 'inherit'}
					w='full'
					height='60px'
					background='gray.50'
					my={2}
					cursor='pointer'
					display='flex'
					alignItems='center'
					justifyContent='center'
				>
					Toolbar
				</Box>
				<Box
					id='calendar'
					onClick={handleSelectView}
					borderRadius={settings.radius.calendarView}
					border={selectedView === 'calendar' ? '2px solid' : 'inherit'}
					w='full'
					height='400px'
					background='gray.50'
					my={2}
					cursor='pointer'
					display='flex'
					alignItems='center'
					justifyContent='center'
				>
					Calendar View
				</Box>
			</Box>
		</Box>
	);
};
